Program Definition Props : Category := {|
  obj     := Prop;
  hom     := Basics.impl;
  homset  := fun P Q => {| equiv := fun f g => True |};
  id      := fun _ x => x;
  compose := fun _ _ _ g f x => g (f x)
|}.   (* thin: at most one arrow, so this IS a preorder viewed as a category *)

Program Instance Props_Cartesian : @Cartesian Props := {
  product_obj := and;   (* P × Q = P ∧ Q, the meet *)
  fork := fun _ _ _ f g x => conj (f x) (g x);
  exl  := fun _ _ p => proj1 p;
  exr  := fun _ _ p => proj2 p }.

Program Instance Props_Closed : @Closed Props _ := {
  exponent_obj := Basics.impl;   (* Q ^ P = P → Q, the relative pseudo-complement *)
  exp_iso := fun _ _ _ =>
    {| to   := {| morphism := fun f a b => f (conj a b) |}
     ; from := {| morphism := fun f p => f (proj1 p) (proj2 p) |} |} }.

#[export] Program Instance exp_one {x : C} :
  x^1 ≅ x := {
  to   := eval ∘ id △ one;
  from := curry exl
}.   (* in Section Closed, under Context {C : Category}, `{@Cartesian C}`, `{@Closed}`, `{@Terminal C}` *)

#[export] Program Instance exp_prod_l {x y z : C} :
  z^(x × y) ≅ (z^y)^x := {
  to   := curry (curry (eval ∘ to prod_assoc));
  from := curry (uncurry eval ∘ from prod_assoc)
}.

Program Definition mate_iso : @Isomorphism Sets mate_dom mate_cod := {|
  to   := {| morphism := mate |};
  from := {| morphism := mate_inv |}
|}.   (* mate_dom := (f' ∘∘∘ a) ~{bicat x y'}~> (b ∘∘∘ f); mate_cod := (a ∘∘∘ u) ~{bicat y x'}~> (u' ∘∘∘ b) *)

Program Definition Adj (C D : Category) : Category := {|
  obj := ∃ (F : D ⟶ C) (U : C ⟶ D), F ⊣ U;
  hom := fun x y => (`1 x ⟹ `1 y) ∧ (`1`2 x ⟹ `1`2 y);
  id  := fun x => (nat_id, nat_id);
  compose := fun _ _ _ f g => (fst f ∙ fst g, snd f ∙ snd g)
|}.

Program Instance Sets_Closed : @Closed Sets _ := {
  exponent_obj := fun x y => {| carrier := SetoidMorphism x y ; is_setoid := @SetoidMorphism_Setoid x y |};
  exp_iso := fun _ _ _ => {| to := {| morphism := fun f => {| morphism := fun x => {| morphism := fun y => f (x, y) |} |} |} ; from := {| morphism := fun f => {| morphism := fun p => f (fst p) (snd p) |} |} |} }.   (* the bijection Hom(S × T, R) ≅ Hom(S, R^T) for setoids *)
